{
  "name": "loss_rankgap_tanh_advantage",
  "intuition": "Shift from margin-based pairwise losses to a rank-gap based paradigm using the advantage signals and a smooth tanh link to penalize ranking errors proportionally to rank gap magnitude.",
  "pseudocode": "rank_gap = advantage_gap\nscaled_gap = clamp(alpha * rank_gap, -10, 10)\nloss_per_pair = relu(tanh(scaled_gap) - (log_prob_w - log_prob_l))\nweighted_loss = loss_per_pair * weight\nfinal_loss = mean(weighted_loss)",
  "hyperparams": {
    "paradigm_family": "pairwise_rank_gap",
    "signal_family": "advantage_gap",
    "link_family": "tanh",
    "agg_family": "mean",
    "constraint_family": "clamp_nonneg_relu"
  },
  "operators_used": ["clamp", "tanh", "relu", "mean", "sub", "mul"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', lpw.new_ones(lpw.shape))\n    adv_gap = batch.get('advantage_gap', batch.get('advantage_w', lpw.new_zeros(lpw.shape)) - batch.get('advantage_l', lpw.new_zeros(lpw.shape)))\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    scaled_gap = ops.clamp(alpha * adv_gap, -10.0, 10.0)\n    link_val = ops.tanh(scaled_gap)\n    diff_log_prob = lpw - lpl\n    raw_loss = ops.relu(link_val - diff_log_prob)\n    raw_loss = raw_loss * weight\n    return ops.mean(raw_loss)"
}

{
  "name": "loss_advantage_tanh_rank_000",
  "intuition": "Repaired pairwise loss using log-prob gap scaled by cost_gap through tanh and relu, ensuring gradient flow.",
  "pseudocode": "log_prob_diff = lpw - lpl; smooth = tanh(cost_gap * scale); loss = weight * relu(-log_prob_diff * smooth); return mean(loss)",
  "hyperparams": {
    "paradigm_family": "pairwise_margin",
    "signal_family": "cost_gap",
    "link_family": "tanh",
    "agg_family": "mean",
    "constraint_family": "relu_zero_clip"
  },
  "operators_used": ["sub", "mul", "tanh", "relu", "neg", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch['weight']\n    cost_gap = batch['cost_gap']\n    scale = float(extra.get('hyperparams', {}).get('scale', 2.0))\n    log_prob_diff = ops.sub(lpw, lpl)\n    smooth = ops.tanh(ops.mul(cost_gap, scale))\n    loss = ops.mul(weight, ops.relu(ops.neg(ops.mul(log_prob_diff, smooth))))\n    return ops.mean(loss)"
}

