{
  "name": "loss_rank_gap_tanh_advantage",
  "intuition": "Rank-based loss using log-probabilities and cost-gap scaling to ensure differentiability and preference strength.",
  "pseudocode": "rank_gap = rank_gap(log_prob_w, log_prob_l)\\nscaled_gap = tanh(beta * rank_gap)\\nloss = weight * (1 - scaled_gap) * abs(cost_gap)\\nmean loss",
  "hyperparams": {
    "paradigm_family": "pairwise_rank_based",
    "signal_family": "cost_gap",
    "link_family": "tanh",
    "agg_family": "mean",
    "constraint_family": "none"
  },
  "operators_used": ["rank_gap", "tanh", "abs", "sub", "mul", "mean", "zeros_like"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    cost_gap = batch.get('cost_gap', ops.zeros_like(lpw))\n    beta = float(extra.get('beta', extra.get('hyperparams', {}).get('beta', 1.0)))\n    rank_g = ops.rank_gap(lpw, lpl)\n    scale = ops.abs(cost_gap) + 1e-8\n    loss = weight * (1 - ops.tanh(beta * rank_g)) * scale\n    return loss.mean()"
}

{
  "name": "pairwise_cost_gap_obj_loss",
  "intuition": "This loss encourages ordering of pairs based on the cost gap signal, using softplus to ensure stable gradients and prevent saturation. It promotes preference for lower-cost choices while remaining differentiable.",
  "pseudocode": "loss = mean( softplus( (log_prob_l - log_prob_w) * cost_gap ) * weight )",
  "hyperparams": {
    "paradigm_family": "pairwise_comparison",
    "signal_family": "cost",
    "link_family": "difference",
    "agg_family": "mean",
    "constraint_family": "none",
    "other_hparams": ""
  },
  "operators_used": ["softplus", "sub", "mul", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    cost_gap = batch.get('cost_gap', ops.zeros_like(lpw))\n    diff = ops.sub(lpl, lpw)\n    weighted_diff = ops.mul(diff, cost_gap)\n    hinge_loss = ops.softplus(weighted_diff)\n    loss = ops.mean(ops.mul(weight, hinge_loss))\n    return loss"
}

{
  "name": "pairwise_pref_loss",
  "intuition": "Uses a pairwise comparison of log probabilities weighted by costs or advantages to encourage preferred sequences. By combining the difference in log probabilities (indicating preference strength) with a cost or advantage signal, it promotes selecting higher-quality outputs. The signal ensures the loss aligns with the objective, especially in lower-is-better scenarios, making it suitable for preference-based training in RL4CO.",
  "pseudocode": "loss = mean(negative(logsigmoid((log_prob_w - log_prob_l) * weight)) * (cost_signal))",
  "hyperparams": {
    "paradigm_family": "preference",
    "signal_family": "cost_advantage",
    "link_family": "sigmoid",
    "agg_family": "pairwise",
    "constraint_family": "pairwise"
  },
  "operators_used": ["logsigmoid", "tanh", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    eps = 1e-8\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    weight = batch['weight']\n    cost_gap = batch['cost_gap']\n    diff = log_prob_w - log_prob_l\n    weighted_diff = diff * weight\n    loss = -ops.logsigmoid(weighted_diff)\n    cost_signal = ops.tanh(cost_gap)\n    return ops.mean(loss * cost_signal)"
}

