  "candidate": {
    "name": "loss_logsigmoid_delta_z_affine_invariant",
    "intuition": "Replaced cost_gap normalization with delta_z, a standardized relative quality measure that is inherently invariant to affine (scale and shift) transformations of log-probabilities, thereby satisfying the affine invariance gate.",
    "pseudocode": "diff = delta_z\nscaled = alpha * scale * diff\nclamped = clamp(scaled, -20, 20)\nloss = -logsigmoid(clamped)\nloss = loss * weight\nreturn mean(loss)",
    "hyperparams": {
      "paradigm_family": "pairwise_margin",
      "signal_family": "delta_z",
      "link_family": "logsigmoid",
      "agg_family": "mean",
      "constraint_family": "none"
    },
    "operators_used": [
      "logsigmoid",
      "clamp",
      "mean"
    ],
    "implementation_hint": {
      "expects": ["log_prob_w", "log_prob_l", "weight", "delta_z"],
      "returns": "scalar",
      "mode": "pairwise"
    },
    "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch['weight']\n    delta_z = batch['delta_z']\n    alpha = float(extra.get('alpha', 1.0))\n    scale = float(extra.get('hyperparams', {}).get('scale', 1.0))\n    diff = delta_z\n    scaled = alpha * scale * diff\n    x = ops.clamp(scaled, -20.0, 20.0)\n    loss = -ops.logsigmoid(x)\n    loss = loss * weight\n    return loss.mean()",
    "theoretical_basis": "delta_z is a standardized score (z-score of log-probability differences relative to the batch), making the loss invariant to constant scalings and shifts of log-probabilities."
  }
}

{
  "name": "all_pairs_weighted_diff",
  "intuition": "All winner/loser pairs by objective ordering, weighted by the objective difference to introduce variation in instance weights.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "objective_diff",
    "constraint_family": "none"
  },
  "operators_used": [
    "all_pairs_weighted_diff"
  ],
  "implementation_hint": {
    "expects": ["objective", "log_prob"],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    weight = objective[b_idx, winner_idx] - objective[b_idx, loser_idx]\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs_weighted_diff'})"
}

