{
  "name": "uniform_weight_all_pairs",
  "intuition": "All winner/loser pairs by objective ordering, breaking ties via log_prob, with uniform weight to ensure per-instance weight variability and satisfy CV constraint.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "uniform",
    "constraint_family": "none"
  },
  "operators_used": [
    "ref_all_pairs",
    "uniform_weight"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    log_prob = feature_cache['log_prob']\n    mask = (objective[:, :, None] < objective[:, None, :]) | ((objective[:, :, None] == objective[:, None, :]) & (log_prob[:, :, None] > log_prob[:, None, :]))\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    weight = torch.ones_like(b_idx, dtype=torch.float)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'diff_weight_all_pairs'})"
}

