    "intuition": "Blends margin and rank signals, with margin modulated by instance log-prob std to emphasize pairs where log-prob variability is high, indicating more informative contrasts.",
    "hyperparams": {
      "weight_scale": 1.0,
      "clamp_lo": 0.25,
      "clamp_hi": 4.0,
      "lambda_rank": 1.0,
      "lambda_regret": 0.0,
      "gamma": 0.5
    }
  },
  "loss": {
    "name": "weighted_logsigmoid_gap",
    "template": "weighted_softplus_gap",
    "intuition": "Logsigmoid gap loss matches builder's emphasis on preference strength; logsigmoid provides smoother gradients than softplus for well-separated pairs.",
    "pseudocode": "gap = log_prob_w - log_prob_l; loss = weight * logsigmoid((gap - target_margin) * gap_scale / temperature); return weighted_mean(loss)",
    "hyperparams": {
      "temperature": 1.0,
      "gap_scale": 0.5,
      "target_margin": 0.0
    }
  }
}

